def solve(coins, amount):
    # Fewest coins summing to amount (unlimited supply), -1 if impossible.
    if amount == 0:
        return 0
    if amount < 0:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c > 0 and a - c >= 0 and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

