def solve(matrix):
    # robust determinant handling empty rows
    n = len(matrix)
    if n == 0:
        return 1
    # verify square
    for row in matrix:
        if len(row) != n:
            # not square, treat as 0 determinant
            return 0
    # Use Bareiss algorithm
    A = [row[:] for row in matrix]
    sign = 1
    for k in range(n-1):
        if A[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        pivot = A[k][k]
        prev = A[k-1][k-1] if k>0 else 1
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // prev
            A[i][k] = 0
    return sign * A[n-1][n-1]

