def solve(lst):
    """Flatten a nested list of integers into a single list preserving order.
    Uses an explicit stack to avoid recursion depth limits.
    """
    result = []
    if not isinstance(lst, list):
        # If input is not a list, return empty as per robust handling
        return result
    stack = [lst]
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            # Add elements in reverse to process them in original order
            for sub in reversed(item):
                stack.append(sub)
        else:
            result.append(item)
    return result

