def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes, which is efficient for n up to at least 10^6.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

