def solve(weights, values, capacity):
    """0/1 knapsack: return the maximum total value achievable with given capacity.
    Each item can be taken at most once.
    """
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
